// SOC-002 · generated from the card contract · non-normative
let p_start = datetime(2026-06-01);
let p_end   = datetime(2026-07-01);
let scope        = "prod";
incidents
| where occurred_at >= p_start and occurred_at < p_end
| where scope_id == scope
| where isnotnull(occurred_at) and isnotnull(detected_at)
        and detected_at >= occurred_at
| extend ttd_h = (detected_at - occurred_at) / 1h
| summarize valid_cases = count(),
            p50_h = percentile(ttd_h, 50),
            p90_h = percentile(ttd_h, 90),
            mean_h_supplementary = round(avg(ttd_h), 1)
// empty case base -> no row = n/a, never 0
